class CodecParentheses:
    def serialize(self, root):
        if not root:
            return ""

        def preorder(node):
            if not node:
                return ""

            result = str(node.val)
            if node.children:
                result += "("
                child_results = []
                for child in node.children:
                    child_results.append(preorder(child))
                result += ",".join(child_results)
                result += ")"

            return result

        return preorder(root)

    def deserialize(self, data):
        if not data:
            return None

        index = [0]

        def parse():
            if index[0] >= len(data):
                return None

            # Parse node value
            start = index[0]
            while index[0] < len(data) and data[index[0]].isdigit():
                index[0] += 1

            if start == index[0]:
                return None

            val = int(data[start:index[0]])
            node = Node(val)

            # Check for children
            if index[0] < len(data) and data[index[0]] == '(':
                index[0] += 1  # Skip '('

                while index[0] < len(data) and data[index[0]] != ')':
                    child = parse()
                    if child:
                        node.children.append(child)

                    # Skip comma
                    if index[0] < len(data) and data[index[0]] == ',':
                        index[0] += 1

                if index[0] < len(data):
                    index[0] += 1  # Skip ')'

            return node

        return parse()

